def explain(store: CodexStore, id: str, depth: int = DEFAULT_DEPTH) -> dict:
    """Return the assertion's dict + provenance + recursive, depth-capped evidence chain."""
    return _node(store, id, depth, frozenset())


def _node(store: CodexStore, id: str, depth_left: int, seen: frozenset[str]) -> dict:
    try:
        a = store.get(id)
    except KeyError:
        return {"id": id, "missing": True}
    if id in seen:
        return {"id": id, "circular": True}
    prov = a.provenance
    assert prov is not None  # invariant #1: no assertion exists without provenance
    node: dict = {
        "id": id,
        "assertion": a.to_dict(),
        "provenance": prov.to_dict(),
    }
    if depth_left > 0:
        node["chain"] = [_node(store, e, depth_left - 1, seen | {id}) for e in prov.evidence]
    else:
        node["chain"] = [{"id": e, "truncated": True} for e in prov.evidence]
        if prov.evidence:
            node["truncated"] = True  # hmm — redundant? The chain entries already say truncated.
    return node
