    """Validate then wrap (deep copy — the wrapper owns its dict)."""
    validate(data)
    return SemanticIR(data=copy.deepcopy(data))


def dump(ir: SemanticIR) -> dict:
    """Unwrap the wrapper (returns the dict owned by the wrapper, deterministically)."""
    return ir.to_dict()
