    def from_dict(cls, d: dict) -> Goal:
        return cls(id=d["id"], content=d["content"])


@dataclass(frozen=True)
class Hypothesis:
    """Thin convenience — schema kainos/ir/1 leaves hypotheses free-form."""
    id: str
    statement: str
    confidence: float | None = None

    def to_dict(self) -> dict:
        d: dict = {"id": self.id, "statement": self.statement}
        if self.confidence is not None:
            d["confidence"] = self.confidence
        return d

    @classmethod
    def from_dict(cls, d: dict) -> Hypothesis:
        return cls(id=d["id"], statement=d["statement"], confidence=d.get("confidence"))
