"""Resolver (P1.05) — resolve the dialect AST against the CODEX; never guess.

For every `Class`, its `realizes_as` is verified against the CODEX lexicon and
recorded in the trace (`{term, realized_as, assertion_id}`) — the Class node
itself keeps semantic identity (invariant #2). For every `UnresolvedRef`,
**rotation**: each candidate's CODEX neighborhood (direct `realizes_as` hits plus
hits of the neighbors' direct partners) is collected. Exactly one reachable
realization → the ref is replaced by the corresponding node (`{^, $}` become
Anchors, class-realization values become Classes, everything else a Literal);
several → the ref stays, recorded as `REQUIRES_CONTEXT` with the competing
candidates; none → `UNSEEN`. Anything left unresolved after the walk makes the
pipeline escalate instead of emitting (spec §4).
"""

from __future__ import annotations

from kainos.codex.models import Assertion
from kainos.codex.store import CodexStore
from kainos.regex.emitter import emit
from kainos.regex.ir import (
    Anchor,
    AnchorKind,
    Alternative,
    Class,
    ClassKind,
    Flag,
    Group,
    Literal,
    Node,
    Repeat,
    Sequence,
    UnresolvedRef,
)

__all__ = ["node_from_realization", "resolve"]


def node_from_realization(value: str) -> Node:
    """The dialect node whose emission equals a CODEX realization value."""

    if value == emit(Anchor(kind=AnchorKind.start)):
        return Anchor(kind=AnchorKind.start)
    if value == emit(Anchor(kind=AnchorKind.end)):
        return Anchor(kind=AnchorKind.end)
    for kind in ClassKind:
        if emit(Class(kind=kind)) == value:
            return Class(kind=kind)
    return Literal(text=value)


def _reachable_realizations(codex: CodexStore, candidate: str) -> tuple[list[str], list[str]]:
    """(distinct realization values, assertion ids) reachable from a candidate:
    its direct `realizes_as` hits, plus those of its direct neighbors' terms
    (one hop of rotation)."""

    realizations: list[str] = []
    assertion_ids: list[str] = []

    def _absorb(a: Assertion) -> None:
        if a.object_id not in realizations:
            realizations.append(a.object_id)
        if a.id not in assertion_ids:
            assertion_ids.append(a.id)

    for a in codex.query(subject=candidate, relation="realizes_as"):
        _absorb(a)
    for a in codex.neighbors(candidate, depth=1):
        partner = a.object_id if a.subject.id == candidate else a.subject.id
        if partner != candidate:
            for b in codex.query(subject=partner, relation="realizes_as"):
                _absorb(b)
    return realizations, assertion_ids


def resolve(node: Node, codex: CodexStore) -> tuple[Node, list[dict]]:
    """Resolve a dialect tree against the CODEX. Returns (resolved_tree, trace) —
    the trace is the audit record: one entry per Class verification and per
    reference rotation (its status: resolved / REQUIRES_CONTEXT / UNSEEN)."""

    trace: list[dict] = []
    return _resolve_node(node, codex, trace), trace


def _resolve_node(node: Node, codex: CodexStore, trace: list[dict]) -> Node:
    if isinstance(node, Class):
        hits = codex.query(subject=node.kind.value, relation="realizes_as")
        trace.append(
            {
                "kind": "class",
                "term": node.kind.value,
                "realized_as": hits[0].object_id if hits else None,
                "assertion_id": hits[0].id if hits else None,
            }
        )
        return node  # a class keeps its semantic identity
    if isinstance(node, UnresolvedRef):
        return _resolve_ref(node, codex, trace)
    if isinstance(node, Sequence):
        return Sequence(elements=[_resolve_node(el, codex, trace) for el in node.elements], id=node.id)
    if isinstance(node, Alternative):
        return Alternative(branches=[_resolve_node(b, codex, trace) for b in node.branches], id=node.id)
    if isinstance(node, Repeat):
        return Repeat(node=_resolve_node(node.node, codex, trace), quantifier=node.quantifier, id=node.id)
    if isinstance(node, Group):
        return Group(node=_resolve_node(node.node, codex, trace), id=node.id)
    return node  # Literal / Anchor / Flag: nothing to resolve


def _resolve_ref(ref: UnresolvedRef, codex: CodexStore, trace: list[dict]) -> Node:
    candidates = list(ref.candidates) or [ref.surface]
    realizations: list[str] = []
    assertion_ids: list[str] = []
    via: dict[str, str] = {}
    for cand in candidates:
        reals, ids = _reachable_realizations(codex, cand)
        for r in reals:
            if r not in realizations:
                realizations.append(r)
                via[r] = cand
        assertion_ids.extend(i for i in ids if i not in assertion_ids)

    if len(realizations) == 1:
        value = realizations[0]
        node = node_from_realization(value)
        trace.append(
            {
                "kind": "ref",
                "surface": ref.surface,
                "status": "resolved",
                "resolved_to": f"{type(node).__name__}({value!r})",
                "realization": value,
                "via": via[value],
                "assertion_ids": assertion_ids,
            }
        )
        return node
    if len(realizations) > 1:
        trace.append(
            {
                "kind": "ref",
                "surface": ref.surface,
                "status": "REQUIRES_CONTEXT",
                "candidates": realizations,
                "assertion_ids": assertion_ids,
            }
        )
        return UnresolvedRef(surface=ref.surface, candidates=realizations, id=ref.id)
    trace.append({"kind": "kind": "ref", "surface": ref.surface, "status": "UNSEEN", "assertion_ids": assertion_ids})
    return UnresolvedRef(surface=ref.surface, candidates=[ref.surface], id=ref.id)

"""Test generator (P1.06) — seeded, deterministic example generation.

`generate(node, seed)` returns (positives, negatives) for a **resolved** dialect
tree: positives are concrete strings the pattern's language must contain
(quantifiers expanded to a few in-bounds lengths); negatives each violate one
constraint (wrong literal, wrong class, out-of-range count, broken anchor,
extra suffix) by mutating exactly one element of an otherwise-valid example.
Same tree + same seed → same examples (determinism is the contract; the judge
is what makes them mean anything).
"""

from __future__ import annotations

import itertools
import random

from kainos.regex.ir import (
    Anchor,
    AnchorKind,
    Alternative,
    Class,
    ClassKind,
    Flag,
    Group,
    Literal,
    Node,
    QuantKind,
    Quantifier,
    Repeat,
    Sequence,
    UnresolvedRef,
)

__all__ = ["generate"]

# Concrete representative characters per class (positives instantiate with these).
CLASS_CHAR: dict[ClassKind, str] = {
    ClassKind.digit: "0",
    ClassKind.letter: "a",
    ClassKind.word: "a",
    ClassKind.whitespace: " ",
    ClassKind.any: "x",
}

# A character that does NOT belong to the class (one-constraint-violation mutations).
WRONG_CLASS_CHAR: dict[ClassKind, str] = {
    ClassKind.digit: "a",
    ClassKind.letter: "0",
    ClassKind.whitespace: "a",
    ClassKind.word: " ",
    ClassKind.any: "a",  # unused: `any` matches everything — no class-violation exists
}

_NEG_CAP = 6
_SAMPLE_CAP = 8


def generate(node: Node, seed: int = 0) -> tuple[list[str], list[str]]:
    """(positive examples, negative examples) for a resolved tree. Deterministic
    under a fixed seed. Raises ValueError for trees still containing an
    UnresolvedRef — the pipeline must not test what it cannot justify."""

    if _has_unresolved(node):
        raise ValueError("cannot generate examples for a tree with unresolved references")
    rng = random.Random(seed)
    positives = _samples(node, "", rng, force=None)[:_SAMPLE_CAP]
    negatives = _negatives(node, positives, rng)
    return positives, negatives


def _has_unresolved(node: Node) -> bool:
    if isinstance(node, UnresolvedRef):
        return True
    if isinstance(node, Sequence):
        return any(_has_unresolved(el) for el in node.elements)
    if isinstance(node, Alternative):
        return any(_has_unresolved(b) for b in node.branches)
    if isinstance(node, (Repeat, Group)):
        return _has_unresolved(node.node)
    return False


def _counts(q: Quantifier) -> list[int]:
    """A few in-bounds copy counts to instantiate the quantifier."""

    match q.kind:
        case QuantKind.one_or_more:
            return [1, 2]
        case QuantKind.zero_or_more:
            return [0, 2]
        case QuantKind.optional:
            return [0, 1]
        case QuantKind.exactly:
            return [q.n]
        case QuantKind.at_least:
            return [q.n, q.n + 1]
        case QuantKind.at_most:
            return [0, q.n]
        case QuantKind.between:
            return [q.a, q.b]


def _samples(n: Node, path: str, rng: random.Random, force: dict[str, int] | None) -> list[str]:
    """Concrete strings this node's sub-pattern can produce (bounded)."""

    if isinstance(n, Literal):
        return [n.text]
    if isinstance(n, Class):
        return [CLASS_CHAR[n.kind]]
    if isinstance(n, (Anchor, Flag)):
        return [""]  # zero-width
    if isinstance(n, Group):
        return _samples(n.node, f"{path}.0", rng, force)
    if isinstance(n, Alternative):
        out: list[str] = []
        for i, b in enumerate(n.branches):
            out.extend(_samples(b, f"{path}.{i}", rng, force)[:2])
        return _dedupe(out)
    if isinstance(n, Sequence):
        lists = [_samples(el, f"{path}.{i}", rng, force)[:2] for i, el in enumerate(n.elements)]
        if any(not ls for ls in lists):
            return []
        product = list(itertools.product(*lists))
        if len(product) > 4:
            product = rng.sample(product, 4)
        return _dedupe(["".join(p) for p in product])
    if isinstance(n, Repeat):
        child = _samples(n.node, f"{path}.0", rng, force)
        if not child:
            return []
        s = child[0]
        k = force.get(path) if force is not None else None
        counts = [k] if k is not None else _counts(n.quantifier)
        return [s * k for k in counts]
    raise ValueError(f"cannot sample node {type(n)!r}")


def _dedupe(items: list[str]) -> list[str]:
    out: list[str] = []
    for x in items:
        if x not in out:
            out.append(x)
    return out


# ── negatives: violate exactly one constraint ──────────────────────────────


def _negatives(root: Node, positives: list[str], rng: random.Random) -> list[str]:
    negatives: list[str] = []

    def add(s: str) -> None:
        if s and s not in positives and s not in negatives and len(negatives) < _NEG_CAP:
            negatives.append(s)

    base = positives[0] if positives else ""

    def swap_once(s: str, old: str, new: str) -> str | None:
        if not old or new == old:
            return None
        idx = s.find(old)
        return None if idx < 0 else s[:idx] + new + s[idx + len(old):]

    def other_char(c: str) -> str:
        return "a" if c != "a" else "0"

    def walk(n: Node, path: str) -> None:
        if isinstance(n, Literal) and n.text:
            mutated = swap_once(base, n.text[:1], other_char(n.text[:1]))
            add(mutated) if mutated else None
        if isinstance(n, Class) and n.kind is not ClassKind.any:
            mutated = swap_once(base, CLASS_CHAR[n.kind], WRONG_CLASS_CHAR[n.kind])
            add(mutated) if mutated else None
        if isinstance(n, Repeat):
            k_bad = _bad_count(n.quantifier)
            if k_bad is not None:
                forced = _samples(root, "", rng, force={path: k_bad})
                if forced:
                    add(forced[0])
        if isinstance(n, Anchor):
            # break the anchor: an anchor-anchored pattern must fail with a stray edge char.
            add("z" + base) if n.kind is AnchorKind.start else add(base + "z")
        for i, child in _children(n):
            walk(child, f"{path}.{i}")

    walk(root, "")

    if not negatives and base and not _ends_wild(root):
        # No structural constraint found: an extra suffix must break full-match.
        add(base + "z")
    return negatives


def _children(n: Node) -> list[tuple[str, Node]]:
    if isinstance(n, Sequence):
        return [(str(i), el) for i, el in enumerate(n.elements)]
    if isinstance(n, Alternative):
        return [(str(i), b) for i, b in enumerate(n.branches)]
    if isinstance(n, (Repeat, Group)):
        return [("0", n.node)]
    return []


def _bad_count(q: Quantifier) -> int | None:
    """An out-of-bounds copy count (None when the quantifier is unbounded)."""

    match q.kind:
        case QuantKind.exactly | QuantKind.at_most:
            return q.n + 1
        case QuantKind.at_least:
            return max(0, (q.n or 0) - 1)
        case QuantKind.between:
            return (q.b or 0) + 1
        case QuantKind.one_or_more:
            return 0
        case _:
            return None


def _ends_wild(n: Node) -> bool:
    """True when the pattern's tail matches ANY extra suffix, so an
    'extra suffix' negative would actually (wrongly) match."""

    n = _tail(n)
    if isinstance(n, Class) and n.kind is ClassKind.any:
        return True
    if isinstance(n, Repeat):
        return (
            q in (QuantKind.one_or_more, QuantKind.zero_or_more)
            and _contains_any(n.node)
            for q in [n.quantifier.kind]
        )[0]
    return False


def _tail(n: Node) -> Node:
    while True:
        if isinstance(n, Group):
            n = n.node
        elif isinstance(n, Sequence) and n.elements:
            n = n.elements[-1]
        else:
            return n


def _contains_any(n: Node) -> bool:
    if isinstance(n, Class):
        return n.kind is ClassKind.any
    if isinstance(n, Sequence):
        return any(_contains_any(el) for el in n.elements)
    if isinstance(n, Alternative):
        return any(_contains_any(b) for b in n.branches)
    if isinstance(n, (Repeat, Group)):
        return _contains_any(n.node)
    return False

