}

sub prj_create {
    my $name     = shift;
    my $slug_raw = shift;
    $slug_raw //= $name;
    my $slug = lc($slug_raw);
    $slug =~ s/[^a-z0-9]+/-/g;
    $slug =~ s/^-+|-+$//g;
    my $body = {
        name         => $name,
        identifier   => $slug,
        description  => { format => 'markdown', raw => $name },
