"""Question parser: 20Q grammar -> Query IR (step 14).

Reuses the Phase-1 kernel PATTERN (template match -> typed IR node; unknown
phrasing -> ``UnresolvedRef`` so the game can ask a clarifying question —
ADR/plan: the parser never invents meaning), applied to the 20Q question
grammar from ``plan/30-phases/phase-2-20questions/game-spec.md``:

    "Is it <property>?"        -> CONSTRAINT  (property = yes/no to be learned)
    "Does it have <property>?" -> CONSTRAINT  (has_<property>)
    "How many <part>?"         -> CONSTRAINT  (<part> = <number>)
    "Is it a <category>?"      -> HYPOTHESIS  (is_a = category)

Unknown wording (a word that is neither a property nor a category) yields
``query=None`` + ``unresolved=[<word>]`` — the game loop turns that into a
clarifying question (C3, honest uncertainty, now at 20Q scale).
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from pathlib import Path

__all__ = ["Query", "ParsedQuestion", "parse_question", "load_questions_index"]

# word -> property for the question grammar (underscore names also accepted)
PROPERTY_WORDS = {
    "alive": "alive",
    "edible": "edible",
    "green": "is_green",
    "wheels": "has_wheels",
    "engine": "has_engine",
    "doors": "has_doors",
    "person": "can_carry_person",
    "water": "lives_in_water",
}
# part -> property for "How many <part>?"
PART_WORDS = {"wheel": "wheel_count", "wheels": "wheel_count"}


@dataclass(frozen=True)
class Query:
    """One parsed 20Q question: a constraint probe or a category hypothesis."""

    kind: str  # "CONSTRAINT" | "HYPOTHESIS"
    property: str | None = None  # CONSTRAINT: property name
    category: str | None = None  # HYPOTHESIS: category name
    question_id: str | None = None  # when it matches a known question


@dataclass(frozen=True)
class ParsedQuestion:
    surface: str
    query: Query | None
    unresolved: tuple[str, ...] = ()


def load_questions_index(path: str | Path | None = None) -> dict[str, dict]:
    """{surface(lower) -> question dict} over the committed question set."""

    if path is None:
        path = Path("data/q20/questions.json")
    records = json.loads(Path(path).read_text())
    return {r["surface"].lower(): r for r in records}


def _word(s: str) -> str:
    return re.sub(r"[^a-z]+", " ", s.lower()).strip()


def parse_question(surface: str, questions: dict[str, dict] | None = None) -> ParsedQuestion:
    """Template-match one surface form. Canonical known surfaces win first."""

    text = surface.strip()
    low = text.lower().rstrip("?").strip()

    if questions is None:
        questions = load_questions_index()
    known = questions.get(low)
    if known is not None:
        kind = "HYPOTHESIS" if known["kind"] == "category_probe" else "CONSTRAINT"
        if kind == "HYPOTHESIS":
            return ParsedQuestion(text, Query(kind, category=known["category"], question_id=known["id"]), ())
        return ParsedQuestion(text, Query(kind, property=known["property"], question_id=known["id"]), ())

    # "How many <part>?"
    m = re.fullmatch(r"how many (.+)", low)
    if m:
        part = _word(m.group(1))
        if part in PART_WORDS:
            return ParsedQuestion(
                text, Query("CONSTRAINT", property=PART_WORDS[part], question_id=f"q_{PART_WORDS[part]}"), ()
            )
        return ParsedQuestion(text, None, (part,))

    # "Does it have <...>?"
    m = re.fullmatch(r"does it have (?:an |a |the )?(.+)", low)
    if m:
        word = _word(m.group(1))
        if word in PROPERTY_WORDS:
            prop = PROPERTY_WORDS[word]
            if not prop.startswith("has_"):
                prop = f"has_{prop}"
            return ParsedQuestion(text, Query("CONSTRAINT", property=prop, question_id=f"q_{prop}"), ())
        return ParsedQuestion(text, None, (word,))

    # "Can it carry <...>?"
    m = re.fullmatch(r"can it (?:carry|hold) (.+)", low)
    if m:
        word = _word(m.group(1))
        if word in PROPERTY_WORDS:
            prop = PROPERTY_WORDS[word]
            return ParsedQuestion(text, Query("CONSTRAINT", property=prop, question_id=f"q_{prop}"), ())
        return ParsedQuestion(text, None, (word,))

    # "Is it (a|an|the)? <word>?" — category first, then property
    m = re.fullmatch(r"is it (?:(?:a|an|the) )?(.+)", low)
    if m:
        word = _word(m.group(1))
        categories = {q["category"] for q in questions.values() if q["kind"] == "category_probe"}
        if word in categories:
            return ParsedQuestion(text, Query("HYPOTHESIS", category=word, question_id=f"q_cat_{word}"), ())
        if word in PROPERTY_WORDS:
            prop = PROPERTY_WORDS[word]
            return ParsedQuestion(text, Query("CONSTRAINT", property=prop, question_id=f"q_{prop}"), ())
        # multi-word property surfaces, e.g. "was it made by humans"/"made by humans"
        made = "made by humans" in word or "man made" in word or "man-made" in word
        if made:
            return ParsedQuestion(text, Query("CONSTRAINT", property="manufactured", question_id="q_made"), ())
        return ParsedQuestion(text, None, (word,))

    # no template matched at all
    return ParsedQuestion(text, None, (low,))

"""Hypothesis space over concept ids (step 14).

The learner is rewarded for ELIMINATING possibilities, not for generating
text: ``H`` starts as all concepts, each (question, answer) pair filters it,
and progress is measured in bits of entropy ``log2(|H|)``.
"""

from __future__ import annotations

import math
from dataclasses import dataclass, field

__all__ = ["HypothesisSpace"]

BUCKET_KEYS = ("yes", "no", "unknown", "sometimes")


@dataclass
class HypothesisSpace:
    """``H`` = set of consistent concept ids + query/answer history."""

    concepts: frozenset[str]
    history: list[tuple[str, str | int]] = field(default_factory=list)

    def __init__(self, concept_ids: set[str] | frozenset[str] | list[str] | None = None, *_, all_ids: set[str] | None = None) -> None:
        if concept_ids is None:
            if all_ids is None:
                raise ValueError("HypothesisSpace needs concept_ids or all_ids")
            concept_ids = all_ids
        if isinstance(concept_ids, list):
            concept_ids = set(concept_ids)
        self.concepts = frozenset(concept_ids)

    def __len__(self) -> int:
        return len(self.concepts)

    def apply(self, question: str, answer: str | int) -> int:
        """Filter H by (question, answer) consistency. Returns new |H|."""

        self.history.append((question, answer))
        return len(self.concepts)  # (caller holds the filtered space; see split)

    def filter(self, kept: set[str]) -> "HypothesisSpace":
        """The H consistent with one observed answer."""

        return HypothesisSpace(self.concepts & frozenset(kept))

    def entropy(self) -> float:
        """log2(|H|); 0.0 for |H| <= 1 (a singleton is already 'known')."""

        n = len(self.concepts)
        return math.log2(n) if n > 1 else 0.0

    def split(self, oracle, question) -> dict[str, set[str]]:
        """H partitioned by the oracle's answer to ``question``.

        Keys: ``yes|no|unknown|sometimes`` and ``n:<int>`` for numbered
        answers. The buckets always partition H (disjoint, union = H).
        """

        buckets: dict[str, set[str]] = {k: set() for k in BUCKET_KEYS}
        for c in self.concepts:
            answer = oracle.answer(c, question)
            key = answer if isinstance(answer, str) else f"n:{answer}"
            buckets.setdefault(key, set()).add(c)
        return buckets

"""Hypothesis space over concept ids (step 14).

The learner is rewarded for ELIMINATING possibilities, not for generating
text: ``H`` starts as all concepts, each (question, answer) filters it, and
progress is measured in bits of entropy ``log2(|H|)``.
"""

from __future__ import annotations

import math

__all__ = ["HypothesisSpace", "BUCKET_KEYS"]

BUCKET_KEYS = ("yes", "no", "unknown", "sometimes")


def bucket_key(answer: str | int) -> str:
    """``yes|no|unknown|sometimes`` pass through; ints become ``n:<int>``."""

    return answer if isinstance(answer, str) else f"n:{answer}"


class HypothesisSpace:
    """``H`` = frozenset of consistent concept ids + (question, answer) history."""

    def __init__(self, concept_ids) -> None:
        self.concepts: frozenset[str] = frozenset(concept_ids)
        self.history: list[tuple[str, str | int]] = []

    def __len__(self) -> int:
        return len(self.concepts)

    @staticmethod
    def from_corpus(corpus: list[dict]) -> "HypothesisSpace":
        return HypothesisSpace({c["id"] for c in corpus})

    def apply(self, oracle, question, answer: str | int) -> int:
        """Filter H in place to the concepts consistent with this answer.

        Returns the new |H|. The filtered bucket is exactly the oracle
        partition cell for ``answer`` (see :meth:`split`).
        """

        qid = question if isinstance(question, str) else question["id"]
        key = bucket_key(answer)
        kept = {c for c in self.concepts if bucket_key(oracle.answer(c, question)) == key}
        self.concepts = frozenset(kept)
        self.history.append((qid, answer))
        return len(self.concepts)

    def entropy(self) -> float:
        """log2(|H|); 0.0 for |H| <= 1 (a singleton is already 'known')."""

        n = len(self.concepts)
        return math.log2(n) if n > 1 else 0.0

    def split(self, oracle, question) -> dict[str, set[str]]:
        """H partitioned by the oracle's answer to ``question``.

        Keys: ``yes|no|unknown|sometimes`` and ``n:<int>`` for numbered
        answers. The buckets always partition H (disjoint, union = H).
        """

        buckets: dict[str, set[str]] = {}
        for c in self.concepts:
            key = bucket_key(oracle.answer(c, question))
            buckets.setdefault(key, set()).add(c)
        return buckets

