        unless 200 <= $r->{status} && $r->{status} < 300;
    return decode_json($r->{content});
};
my $st = $J->("/statuses");
my ($closed) = grep { $_->{name} eq "Closed" } @{ $st->{_embedded}{elements} };
die "no Closed status\n" unless $closed;
