def _codex_add(store: SqliteCodexStore, path: str) -> int:
    try:
        raw = Path(path).read_text(encoding="utf-8")
    except OSError as e:
        raise CliError(f"cannot read {path}: {e}") from None
    try:
        data = json.loads(raw)
