class E1_5Experiment:
    """Registered as `e1.5` — the Phase 1 headline A/B (and sign-off gate)."""

    name = "e1.5"
    hypothesis = (
        "on combinations absent from training, the CODEX pipeline (B) beats the "
        "conventional next-token baseline (A) on accuracy, and B abstains "
        "correctly on underspecified input where A cannot"
    )
    metric = "holdout accuracy A vs B (+ exact McNemar), vague-set abstention"
    threshold = "B > A and exact McNemar p <= 0.20 (n=20 matched pairs)"

    def run(self) -> Result:
        # Local import breaks the runner <-> experiment import cycle.
        from kainos.harness.runner import Result

        report = run_e1_5()
        return Result(
            name=self.name,
            passed=bool(report["passed"]),
            value=report["pipeline_accuracy"],
            evidence=[Path("results/phase-1/e1.5.json"), Path("results/phase-1/e1.5.md")],
            config={
                "baseline_accuracy": report["baseline_accuracy"],
                "margin": report["margin"],
                "mcnemar_p": report["mcnemar_p"],
                "vague": report["vague"],
                "model_a_weights_sha256": report["config"]["model_a"]["weights_sha256"],
            },
        )
def run_experiments(exps: Sequence[Experiment], out_dir: Path = RESULTS_DIR) -> tuple[list[Result], int]:
    results: list[Result] = []
    rc = 0
    print(f"running {len(exps)} experiment(s) [commit {git_commit()}]")
    for exp in exps:
        r = run(exp, out_dir)
        results.append(r)
        mark = "PASS" if r.passed else "FAIL"
        print(f"{mark}  {r.name}: {r.value} (threshold: {r.threshold}) — {out_dir / (r.name + '.md')}")
        rc = rc or (0 if r.passed else 1)
    return results, rc


def load_results(out_dir: Path = RESULTS_DIR, phase: int | None = None) -> list[dict]:
    """Persisted result JSONs (flat and `phase-*/` subdirs), optionally filtered to a phase
    via the `e<phase>.` registry-key prefix."""

    files = sorted(out_dir.glob("*.json")) + sorted(out_dir.glob("phase-*/*.json"))
    short_names_by_phase: dict[str, set[str]] = {}
    for key in REGISTRY:
        if "." in key:
            short_names_by_phase.setdefault(key.split(".", 1)[0], set()).add(key.split(".", 1)[-1])
    out = []
    for f in files:
        try:
            d = json.loads(f.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            continue
        # A result record has a fixed shape; this skips non-result JSON in the
        # same directory (e.g. evidence artifacts).
        if not isinstance(d, dict) or not {"name", "passed", "config"} <= d.keys():
            continue
        if phase is not None:
            key = f"e{phase}."
            if d["name"] not in short_names_by_phase.get(key, set()):
                continue
